1	//! The main window of the application, from which all main functionality is
2	//! reached: a toolbar on top, and below it the project tree in a sidebar on the
3	//! left, then prompt mode with the harness stream split beside it while raw
4	//! output is shown.
5	
6	use gpui_kit::component::resizable::{ResizableState, h_resizable, resizable_panel};
7	use gpui_kit::component::{ActiveTheme, Root, WindowExt as _};
8	use gpui_kit::*;
9	
10	use crate::app::APP_TITLE;
11	use crate::harness_stream::HarnessStream;
12	use crate::palette::{Palette, Picked, SystemCommand, SystemState};
13	use crate::project_tree::{OpenFile, ProjectTree};
14	use crate::prompt_mode::PromptMode;
15	use crate::theme_preference;
16	use crate::toolbar::{self, RawOutputToggled, Toolbar};
17	
18	/// Size the window restores to when it is un-maximized.
19	const RESTORE_SIZE: Size<Pixels> = size(px(1280.), px(800.));
20	
21	/// The narrowest a split can be dragged.
22	const MIN_SPLIT_WIDTH: Pixels = px(240.);
23	
24	/// The sidebar's width until it is dragged, and the narrowest it can be.
25	const SIDEBAR_WIDTH: Pixels = px(260.);
26	const MIN_SIDEBAR_WIDTH: Pixels = px(160.);
27	
28	actions!(suspense, [FocusChat, TogglePalette]);
29	
30	/// Esc anywhere in the window moves focus to the chat input. It is bound
31	/// without a context, so an editor or popup that has something to cancel
32	/// (a completion menu, extra cursors) takes Esc first. Ctrl/Cmd+P opens or
33	/// closes the palette.
34	pub fn bind_keys(cx: &mut App) {
35	    cx.bind_keys([
36	        KeyBinding::new("escape", FocusChat, None),
37	        #[cfg(target_os = "macos")]
38	        KeyBinding::new("cmd-p", TogglePalette, None),
39	        #[cfg(not(target_os = "macos"))]
40	        KeyBinding::new("ctrl-p", TogglePalette, None),
41	    ]);
42	    crate::palette::bind_keys(cx);
43	}
44	
45	pub struct MainWindow {
46	    toolbar: Entity<Toolbar>,
47	    sidebar: Entity<ProjectTree>,
48	    prompt_mode: Entity<PromptMode>,
49	    stream: Option<Entity<HarnessStream>>,
50	    /// The palette last opened, which may since have closed.
51	    palette: Option<Entity<Palette>>,
52	    _palette_subscription: Option<Subscription>,
53	    /// Kept apart from `splits` so the sidebar keeps its width when the
54	    /// stream split opens or closes.
55	    sidebar_split: Entity<ResizableState>,
56	    splits: Entity<ResizableState>,
57	    _subscriptions: Vec<Subscription>,
58	}
59	
60	impl MainWindow {
61	    pub fn open(cx: &mut App) -> Result<WindowHandle<Root>> {
62	        let options = WindowOptions {
63	            window_bounds: Some(WindowBounds::Maximized(Bounds::centered(
64	                None,
65	                RESTORE_SIZE,
66	                cx,
67	            ))),
68	            titlebar: Some(TitlebarOptions {
69	                title: Some(APP_TITLE.into()),
70	                ..Default::default()
71	            }),
72	            ..Default::default()
73	        };
74	
75	        cx.open_window(options, |window, cx| {
76	            // Start in the saved light or dark mode, else the system's; the
77	            // toolbar can switch.
78	            theme_preference::apply(window, cx);
79	            let view = cx.new(|cx| MainWindow::new(window, cx));
80	            cx.new(|cx| Root::new(view, window, cx))
81	        })
82	    }
83	
84	    pub fn new(window: &mut Window, cx: &mut Context<Self>) -> Self {
85	        let toolbar = cx.new(Toolbar::new);
86	        let sidebar = cx.new(ProjectTree::new);
87	        let subscriptions = vec![
88	            cx.subscribe_in(
89	                &toolbar,
90	                window,
91	                |this, _, event: &RawOutputToggled, window, cx| {
92	                    this.show_stream(event.visible, window, cx)
93	                },
94	            ),
95	            cx.subscribe_in(&sidebar, window, |this, _, OpenFile(path), window, cx| {
96	                this.prompt_mode.update(cx, |prompt_mode, cx| {
97	                    prompt_mode.open_file(path.clone(), window, cx)
98	                })
99	            }),
100	            // Until light or dark mode is chosen, the window keeps following
101	            // the system's appearance as it changes.
102	            cx.observe_window_appearance(window, |_, window, cx| {
103	                theme_preference::apply(window, cx)
104	            }),
105	            // Focus left on nothing, as when a focused file is closed, would
106	            // put Esc out of the window's reach; the chat input takes it.
107	            cx.on_focus_lost(window, |this, window, cx| {
108	                this.prompt_mode
109	                    .update(cx, |prompt_mode, cx| prompt_mode.focus_chat(window, cx))
110	            }),
111	        ];
112	
113	        Self {
114	            toolbar,
115	            sidebar,
116	            prompt_mode: cx.new(|cx| PromptMode::new(window, cx)),
117	            stream: None,
118	            palette: None,
119	            _palette_subscription: None,
120	            sidebar_split: cx.new(|_| ResizableState::default()),
121	            splits: cx.new(|_| ResizableState::default()),
122	            _subscriptions: subscriptions,
123	        }
124	    }
125	
126	    fn show_stream(&mut self, visible: bool, window: &mut Window, cx: &mut Context<Self>) {
127	        self.stream = visible.then(|| cx.new(|cx| HarnessStream::new(window, cx)));
128	        // Fresh split sizes, so none are left over from a closed split.
129	        self.splits = cx.new(|_| ResizableState::default());
130	        cx.notify();
131	    }
132	
133	    /// Opens a fresh palette on the Files tab, or closes the one open.
134	    fn toggle_palette(&mut self, window: &mut Window, cx: &mut Context<Self>) {
135	        if let Some(palette) = &self.palette
136	            && palette.read(cx).is_open(window, cx)
137	        {
138	            window.close_dialog(cx);
139	            return;
140	        }
141	        let toolbar = self.toolbar.read(cx);
142	        let system = SystemState {
143	            raw_output_visible: toolbar.raw_output_visible(),
144	            can_build: toolbar.can_build(cx),
145	            dark: cx.theme().is_dark(),
146	        };
147	        let palette = cx.new(|cx| Palette::new(system, window, cx));
148	        self._palette_subscription = Some(cx.subscribe_in(
149	            &palette,
150	            window,
151	            |this, _, picked: &Picked, window, cx| this.run_picked(picked, window, cx),
152	        ));
153	        Palette::open(&palette, window, cx);
154	        self.palette = Some(palette);
155	    }
156	
157	    fn run_picked(&mut self, picked: &Picked, window: &mut Window, cx: &mut Context<Self>) {
158	        match picked {
159	            Picked::File(path) => self.prompt_mode.update(cx, |prompt_mode, cx| {
160	                prompt_mode.open_file(path.clone(), window, cx)
161	            }),
162	            Picked::Mention(mention) => self.prompt_mode.update(cx, |prompt_mode, cx| {
163	                prompt_mode.insert_mention(mention, window, cx)
164	            }),
165	            Picked::System(command) => match command {
166	                SystemCommand::OpenProject => self
167	                    .toolbar
168	                    .update(cx, |toolbar, cx| toolbar.pick_project(window, cx)),
169	                SystemCommand::Build => self
170	                    .toolbar
171	                    .update(cx, |toolbar, cx| toolbar.build(window, cx)),
172	                SystemCommand::ToggleRawOutput => self
173	                    .toolbar
174	                    .update(cx, |toolbar, cx| toolbar.toggle_raw_output(cx)),
175	                SystemCommand::ToggleDarkMode => {
176	                    toolbar::set_dark_mode(!cx.theme().is_dark(), window, cx)
177	                }
178	                SystemCommand::Quit => cx.quit(),
179	            },
180	        }
181	    }
182	}
183	
184	impl Render for MainWindow {
185	    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
186	        div()
187	            .size_full()
188	            .flex()
189	            .flex_col()
190	            .bg(cx.theme().background)
191	            .text_color(cx.theme().foreground)
192	            .on_action(cx.listener(|this, _: &FocusChat, window, cx| {
193	                // The context-less Esc binding outranks the palette's own, so
194	                // the palette's Esc is handled here.
195	                if let Some(palette) = &this.palette
196	                    && palette.read(cx).is_open(window, cx)
197	                {
198	                    palette.update(cx, |palette, cx| palette.cancel(window, cx));
199	                    return;
200	                }
201	                this.prompt_mode
202	                    .update(cx, |prompt_mode, cx| prompt_mode.focus_chat(window, cx))
203	            }))
204	            .on_action(
205	                cx.listener(|this, _: &TogglePalette, window, cx| this.toggle_palette(window, cx)),
206	            )
207	            .child(self.toolbar.clone())
208	            .child(
209	                div().flex_1().min_h_0().child(
210	                    // One `children` call for every panel: the group's
211	                    // `children` replaces panels added before it.
212	                    h_resizable("sidebar-split")
213	                        .with_state(&self.sidebar_split)
214	                        .children([
215	                            resizable_panel()
216	                                .size(SIDEBAR_WIDTH)
217	                                .size_range(MIN_SIDEBAR_WIDTH..Pixels::MAX)
218	                                .child(self.sidebar.clone()),
219	                            resizable_panel()
220	                                .size_range(MIN_SPLIT_WIDTH..Pixels::MAX)
221	                                .child(
222	                                    h_resizable("body").with_state(&self.splits).children(
223	                                        std::iter::once(
224	                                            resizable_panel()
225	                                                .size_range(MIN_SPLIT_WIDTH..Pixels::MAX)
226	                                                .child(self.prompt_mode.clone()),
227	                                        )
228	                                        .chain(
229	                                            self.stream.iter().map(|stream| {
230	                                                let split = div()
231	                                                    .id("stream")
232	                                                    .size_full()
233	                                                    .child(stream.clone());
234	                                                resizable_panel()
235	                                                    .size_range(MIN_SPLIT_WIDTH..Pixels::MAX)
236	                                                    // Lets UI tests find the split; inert in normal builds.
237	                                                    .child(gpui_kit::TestSupportExt::test_support(
238	                                                        split,
239	                                                    ))
240	                                            }),
241	                                        ),
242	                                    ),
243	                                ),
244	                        ]),
245	                ),
246	            )
247	            // Inside the window's element tree, so actions such as
248	            // TogglePalette reach it from a focused dialog.
249	            .children(Root::render_dialog_layer(window, cx))
250	            .children(Root::render_notification_layer(window, cx))
251	    }
252	}
253	
254	#[cfg(test)]
255	mod tests {
256	    // Explicit imports: globbing `gpui_kit::*` would bring in GPUI's `test`
257	    // macro and shadow Rust's `#[test]`.
258	    use std::time::Duration;
259	
260	    use gpui_kit::component::Root;
261	    use gpui_kit::test::{TestAppContextExt as _, TestWindowExt as _};
262	    use gpui_kit::{AppContext as _, TestAppContext};
263	
264	    use super::MainWindow;
265	    use crate::harness_run::HarnessRuns;
266	    use crate::piton_syntax;
267	    use crate::project_directory::ProjectDirectory;
268	
269	    const TIMEOUT: Duration = Duration::from_secs(2);
270	
271	    /// The chat input has focus as soon as the window opens: a prompt typed
272	    /// and sent without clicking anywhere is sent, which without a project
273	    /// open shows a notification saying so.
274	    #[gpui_kit::test]
275	    async fn chat_input_is_focused_when_the_window_opens(cx: &mut TestAppContext) {
276	        cx.update(|cx| {
277	            gpui_kit::init(cx);
278	            piton_syntax::init();
279	            ProjectDirectory::init(cx);
280	            HarnessRuns::init(cx);
281	        });
282	        let window = cx.add_window(|window, cx| {
283	            let view = cx.new(|cx| MainWindow::new(window, cx));
284	            Root::new(view, window, cx)
285	        });
286	        let handle = window.into();
287	        cx.wait_for(handle, TIMEOUT, |window, _| {
288	            window.try_find("prompt-editor").is_some()
289	        })
290	        .await;
291	
292	        for key in "hello".chars() {
293	            cx.update_window(handle, |_, window, cx| window.input(&key.to_string(), cx))
294	                .unwrap();
295	            cx.run_until_parked();
296	        }
297	        #[cfg(target_os = "macos")]
298	        let send = "cmd-enter";
299	        #[cfg(not(target_os = "macos"))]
300	        let send = "ctrl-enter";
301	        cx.update_window(handle, |_, window, cx| window.press(send, cx))
302	            .unwrap();
303	
304	        cx.wait_for(handle, TIMEOUT, |window, _| {
305	            window.try_find("notification").is_some()
306	        })
307	        .await;
308	    }
309	
310	    /// The toolbar's raw output toggle splits a harness stream off to the
311	    /// right of prompt mode, inside the window, and closes it again.
312	    #[gpui_kit::test]
313	    async fn raw_output_toggle_shows_and_hides_the_stream(cx: &mut TestAppContext) {
314	        cx.update(|cx| {
315	            gpui_kit::init(cx);
316	            piton_syntax::init();
317	            ProjectDirectory::init(cx);
318	            HarnessRuns::init(cx);
319	        });
320	        let window = cx.add_window(|window, cx| {
321	            let view = cx.new(|cx| MainWindow::new(window, cx));
322	            Root::new(view, window, cx)
323	        });
324	        let handle = window.into();
325	
326	        cx.wait_for(handle, TIMEOUT, |window, _| {
327	            window.try_find("raw-output").is_some()
328	        })
329	        .await;
330	        cx.update_window(handle, |_, window, cx| window.click("raw-output", cx))
331	            .unwrap();
332	        cx.wait_for(handle, TIMEOUT, |window, _| {
333	            window.try_find("stream").is_some()
334	        })
335	        .await;
336	
337	        // The split settles its panel sizes over the frames after it measures
338	        // its container.
339	        for _ in 0..3 {
340	            cx.run_until_parked();
341	            cx.update_window(handle, |_, window, cx| window.render_frame(cx))
342	                .unwrap();
343	        }
344	
345	        cx.update_window(handle, |_, window, cx| {
346	            window.render_frame(cx);
347	            let viewport = window.viewport_size();
348	            let send = window.find("send").bounds();
349	            let stream = window.find("stream").bounds();
350	            assert!(
351	                stream.left() >= send.right() && stream.size.width > gpui_kit::px(0.),
352	                "stream is not beside prompt mode (Send at {send:?}): {stream:?} in {viewport:?}"
353	            );
354	            assert!(
355	                stream.right() <= viewport.width + gpui_kit::px(1.),
356	                "stream runs past the window: {stream:?} in {viewport:?}"
357	            );
358	        })
359	        .unwrap();
360	
361	        cx.update_window(handle, |_, window, cx| window.click("raw-output", cx))
362	            .unwrap();
363	        cx.wait_for(handle, TIMEOUT, |window, _| {
364	            window.try_find("stream").is_none()
365	        })
366	        .await;
367	    }
368	
369	    /// Clicking a file in the project tree opens it beside the chat history,
370	    /// taking 50% of the width; the chat input stays unsplit below both.
371	    #[gpui_kit::test]
372	    async fn clicking_a_file_opens_it_beside_the_chat_history(cx: &mut TestAppContext) {
373	        let dir = std::env::temp_dir().join(format!("suspense-open-file-{}", std::process::id()));
374	        let _ = std::fs::remove_dir_all(&dir);
375	        std::fs::create_dir_all(&dir).unwrap();
376	        std::fs::write(dir.join("notes.md"), "# Notes\n").unwrap();
377	
378	        cx.update(|cx| {
379	            gpui_kit::init(cx);
380	            piton_syntax::init();
381	            ProjectDirectory::init(cx);
382	            HarnessRuns::init(cx);
383	        });
384	        let window = cx.add_window(|window, cx| {
385	            let view = cx.new(|cx| MainWindow::new(window, cx));
386	            Root::new(view, window, cx)
387	        });
388	        let handle = window.into();
389	
390	        cx.update(|cx| ProjectDirectory::set(dir.clone(), cx));
391	        cx.wait_for(handle, TIMEOUT, |window, _| {
392	            window.try_find(("project-entry", 0usize)).is_some()
393	        })
394	        .await;
395	        cx.update_window(handle, |_, window, cx| {
396	            window.click(("project-entry", 0usize), cx)
397	        })
398	        .unwrap();
399	        cx.wait_for(handle, TIMEOUT, |window, _| {
400	            window.try_find("file-view").is_some()
401	        })
402	        .await;
403	        for _ in 0..3 {
404	            cx.run_until_parked();
405	            cx.update_window(handle, |_, window, cx| window.render_frame(cx))
406	                .unwrap();
407	        }
408	
409	        cx.update_window(handle, |_, window, cx| {
410	            window.render_frame(cx);
411	            let file = window.find("file-view").bounds();
412	            let history = window.find("history").bounds();
413	            let editor = window.find("prompt-editor").bounds();
414	            let send = window.find("send").bounds();
415	            let share = file.size.width / (file.size.width + history.size.width);
416	            assert!(
417	                (share - 0.5).abs() < 0.02,
418	                "file takes {share} of the width: {file:?} beside {history:?}"
419	            );
420	            assert!(
421	                history.left() >= file.right() - gpui_kit::px(1.),
422	                "history is not right of the file: {file:?} then {history:?}"
423	            );
424	            assert!(
425	                editor.top() >= file.bottom()
426	                    && editor.left() < file.right()
427	                    && send.right() > history.left(),
428	                "chat input (editor {editor:?}, Send {send:?}) is split with the file {file:?}"
429	            );
430	        })
431	        .unwrap();
432	
433	        cx.update_window(handle, |_, window, cx| window.click("close-file", cx))
434	            .unwrap();
435	        cx.wait_for(handle, TIMEOUT, |window, _| {
436	            window.try_find("file-view").is_none()
437	        })
438	        .await;
439	
440	        std::fs::remove_dir_all(&dir).ok();
441	    }
442	
443	    /// Esc in an open file moves focus back to the chat input, where typing
444	    /// then lands.
445	    #[gpui_kit::test]
446	    async fn escape_in_a_file_focuses_the_chat_input(cx: &mut TestAppContext) {
447	        let dir = std::env::temp_dir().join(format!("suspense-escape-{}", std::process::id()));
448	        let _ = std::fs::remove_dir_all(&dir);
449	        std::fs::create_dir_all(&dir).unwrap();
450	        std::fs::write(dir.join("notes.md"), "# Notes\n").unwrap();
451	
452	        cx.update(|cx| {
453	            gpui_kit::init(cx);
454	            piton_syntax::init();
455	            ProjectDirectory::init(cx);
