100	}
101	
102	/// A sent prompt once compiled.
103	struct Compiled {
104	    /// The name of the hidden anchor it was compiled from.
105	    anchor: SharedString,
106	    markdown: String,
107	}
108	
109	#[derive(Clone, Copy, Debug, PartialEq)]
110	enum TaskStatus {
111	    Compiling,
112	    Running,
113	    Done,
114	    Failed,
115	    /// From the history, with no record of what came of it.
116	    Unrecorded,
117	}
118	
119	impl TaskStatus {
120	    fn label(self) -> &'static str {
121	        match self {
122	            Self::Compiling => "Compiling",
123	            Self::Running => "Running",
124	            Self::Done => "Done",
125	            Self::Failed => "Failed",
126	            Self::Unrecorded => "Not recorded",
127	        }
128	    }
129	
130	    fn is_active(self) -> bool {
131	        matches!(self, Self::Compiling | Self::Running)
132	    }
133	
134	    /// A label in the status's colour, with the status spelled out. Uses the
135	    /// palette colours, like the output badges, as the theme's solid status
136	    /// colours are unreadable in dark mode.
137	    fn tag(self) -> Tag {
138	        Tag::color(match self {
139	            Self::Compiling => ColorName::Cyan,
140	            Self::Running => ColorName::Yellow,
141	            Self::Done => ColorName::Green,
142	            Self::Failed => ColorName::Red,
143	            Self::Unrecorded => ColorName::Gray,
144	        })
145	        .text_sm()
146	        .child(self.label())
147	    }
148	}
149	
150	impl PromptTask {
151	    fn new(text: SharedString) -> Self {
152	        Self {
153	            text,
154	            compiled: None,
155	            reply: Reply::default(),
156	            status: TaskStatus::Compiling,
157	        }
158	    }
159	
160	    /// A task from the history, as it ended: its run's output is replayed
161	    /// through the harness's parser.
162	    fn restore(saved: SavedPrompt) -> Self {
163	        let mut task = Self::new(saved.text.into());
164	        let Some(record) = saved.record else {
165	            task.reply.done = true;
166	            task.status = TaskStatus::Unrecorded;
167	            return task;
168	        };
169	        if let Some(markdown) = record.user_prompt {
170	            task.set_compiled(Compiled {
171	                anchor: saved.anchor.name().to_string().into(),
172	                markdown,
173	            });
174	        }
175	        for event in record.output.iter().flat_map(harness::parse) {
176	            task.apply(event);
177	        }
178	        if let Some(error) = record.error {
179	            task.apply(HarnessEvent::Failed(error));
180	        }
181	        task.end();
182	        task
183	    }
184	
185	    fn set_compiled(&mut self, compiled: Compiled) {
186	        self.compiled = Some(compiled);
187	        self.status = TaskStatus::Running;
188	    }
189	
190	    /// Folds a harness event into the task's output and status.
191	    fn apply(&mut self, event: HarnessEvent) {
192	        match self.reply.apply(event) {
193	            Some(error) => self.fail(error),
194	            None if self.reply.done && self.status == TaskStatus::Running => {
195	                self.status = TaskStatus::Done
196	            }
197	            None => {}
198	        }
199	    }
200	
201	    fn fail(&mut self, error: String) {
202	        self.reply.parts.push(ReplyPart::Error(error));
203	        self.status = TaskStatus::Failed;
204	    }
205	
206	    /// The run is over. One that ended without a result, as when the harness
207	    /// was stopped, failed, and nothing still running in it finished.
208	    fn end(&mut self) {
209	        if self.reply.done {
210	            return;
211	        }
212	        self.reply.done = true;
213	        self.reply.settle_tools(ToolState::Failed);
214	        if self.status != TaskStatus::Failed {
215	            self.fail("The harness stopped without a result.".into());
216	        }
217	    }
218	}
219	
220	/// A harness reply as it streams in.
221	#[derive(Default)]
222	pub(crate) struct Reply {
223	    parts: Vec<ReplyPart>,
