    /// The toolbar's raw output toggle splits a harness stream off to the
    /// right of prompt mode, inside the window, and closes it again.
    #[gpui_kit::test]
    async fn raw_output_toggle_shows_and_hides_the_stream(cx: &mut TestAppContext) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            piton_syntax::init();
            ProjectDirectory::init(cx);
            HarnessRuns::init(cx);
        });
        let window = cx.add_window(|window, cx| {
