        });
        let handle = window.into();

        cx.wait_for(handle, TIMEOUT, |window, _| {
            window.try_find("raw-output").is_some()
        })
        .await;
        cx.update_window(handle, |_, window, cx| window.click("raw-output", cx))
            .unwrap();
        cx.wait_for(handle, TIMEOUT, |window, _| {
            window.try_find("stream").is_some()
        })
        .await;

        // The split settles its panel sizes over the frames after it measures
        // its container.
        for _ in 0..3 {
            cx.run_until_parked();
            cx.update_window(handle, |_, window, cx| window.render_frame(cx))
                .unwrap();
        }

        cx.update_window(handle, |_, window, cx| {
