                "history is not right of the file: {file:?} then {history:?}"
            );
            assert!(
                editor.top() >= file.bottom()
                    && editor.left() < file.right()
                    && send.right() > history.left(),
                "chat input (editor {editor:?}, Send {send:?}) is split with the file {file:?}"
            );
