        cx.update_window(handle, |_, window, cx| window.click("close-file", cx))
            .unwrap();
        cx.wait_for(handle, TIMEOUT, |window, _| {
            window.try_find("file-view").is_none()
        })
        .await;

        std::fs::remove_dir_all(&dir).ok();
    }

